
import math
from functools import wraps

# ============================================================
# THE TEN-STATE MATHEMATICAL SEQUENCE
# ] ] @ ? ]! ]$ ]? ![ !@ @@
# ============================================================

SEQUENCE = ["]", "]", "@", "?", "]!", "]$", "]?", "![", "!@", "@@"]

# Each symbol represents a custom mathematical operation.
OPERATIONS = {
    "]":  "add",
    "@":  "multiply",
    "?":  "subtract",
    "]!": "square",
    "]$": "absolute",
    "]?": "modulo",
    "![": "sqrt",
    "!@": "log",
    "@@": "power",
}

CALL_COUNTS = {}


# ============================================================
# DECORATOR 1: TRACE EVERY FUNCTION CALL
# ============================================================

def trace(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print("[TRACE] Entering:", func.__name__)
        result = func(*args, **kwargs)
        print("[TRACE] Leaving:", func.__name__)
        return result
    return wrapper


# ============================================================
# DECORATOR 2: COUNT FUNCTION CALLS
# ============================================================

def count_calls(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        name = func.__name__
        if name not in CALL_COUNTS:
            CALL_COUNTS[name] = 0
        CALL_COUNTS[name] += 1
        return func(*args, **kwargs)
    return wrapper


# ============================================================
# DECORATOR 3: VALIDATE NUMERICAL RESULTS
# ============================================================

def finite_result(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)

        if isinstance(result, (int, float)):
            if not math.isfinite(result):
                raise ValueError("Non-finite numerical result!")

        return result
    return wrapper


# ============================================================
# DECORATOR 4: MEASURE LOGICAL DEPTH
# ============================================================

def announce(level):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            print(f"[LEVEL {level}] {func.__name__}")
            return func(*args, **kwargs)
        return wrapper
    return decorator


# ============================================================
# DECORATOR 5: APPLY A NUMERICAL LIMIT
# ============================================================

def bounded(low=-1_000_000, high=1_000_000):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)

            if result < low:
                return low
            elif result > high:
                return high
            else:
                return result

        return wrapper
    return decorator


# ============================================================
# DECORATOR 6: REPORT BRANCH DECISIONS
# ============================================================

def branch_report(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print("[BRANCH] Evaluating conditions...")
        result = func(*args, **kwargs)

        if result >= 0:
            print("[BRANCH] Non-negative result.")
        else:
            print("[BRANCH] Negative result.")

        return result
    return wrapper


# ============================================================
# MATHEMATICAL ENGINE
# ============================================================

@trace
@count_calls
@finite_result
@announce(1)
@bounded()
@branch_report
def calculate(value, symbol, step):
    """Apply the operation associated with a sequence symbol."""

    if symbol == "]":
        if step % 2 == 0:
            result = value + step
        else:
            result = value + 1

    elif symbol == "@":
        if value == 0:
            result = 1
        else:
            result = value * 2

    elif symbol == "?":
        if value > step:
            result = value - step
        else:
            result = step - value

    elif symbol == "]!":
        if abs(value) < 100:
            result = value ** 2
        else:
            result = abs(value)

    elif symbol == "]$":
        if value < 0:
            result = -value
        else:
            result = value

    elif symbol == "]?":
        divisor = step + 1

        if divisor != 0:
            result = value % divisor
        else:
            result = value

    elif symbol == "![":
        if value >= 0:
            result = math.sqrt(value)
        else:
            result = math.sqrt(abs(value))

    elif symbol == "!@":
        if value > 0:
            result = math.log(value + 1)
        else:
            result = math.log(abs(value) + 1)

    elif symbol == "@@":
        if step % 2 == 0:
            result = value ** 2
        else:
            result = value ** 3

    else:
        # The second occurrence of ] uses this fallback.
        result = value + 1

    return result


# ============================================================
# DECORATED STATE TRANSFORMATION
# ============================================================

@trace
@count_calls
@finite_result
@announce(2)
def transform(value, index):
    if value < 0:
        value = abs(value)
    else:
        value = value + 0.5

    if index % 3 == 0:
        value = value + 2
    elif index % 3 == 1:
        value = value * 1.1
    else:
        value = value - 0.25

    return value


# ============================================================
# DECORATED CONVERGENCE TEST
# ============================================================

@trace
@count_calls
def should_continue(value, iteration, threshold=0.0001):
    if iteration >= 100:
        return False
    elif abs(value) < threshold:
        return False
    else:
        return True


# ============================================================
# SEQUENCE EXECUTION
# ============================================================

@trace
@count_calls
def run_sequence(initial_value=2.0):
    value = initial_value
    index = 0
    history = []

    print("\n" + "=" * 60)
    print("THE SYMBOLIC MATHEMATICAL MACHINE")
    print("=" * 60)
    print("Sequence:", " ".join(SEQUENCE))
    print("Initial value:", value)

    while index < len(SEQUENCE):
        symbol = SEQUENCE[index]

        print("\nSTEP", index + 1, "| SYMBOL:", symbol)
        print("Input:", round(value, 6))

        value = calculate(value, symbol, index + 1)
        value = transform(value, index)

        history.append((index + 1, symbol, value))

        print("Output:", round(value, 6))

        # Additional conditional logic.
        if value > 1000:
            print("WARNING: Large value detected.")
            value = math.sqrt(value)

        elif value > 100:
            print("NOTICE: Applying compression.")
            value = value / 10

        elif value < 1:
            print("NOTICE: Small value detected.")
            value = value + 1

        else:
            print("STATUS: Value within ordinary range.")

        index += 1

    print("\n" + "=" * 60)
    print("FINAL RESULT:", round(value, 8))
    print("=" * 60)

    return history, value


# ============================================================
# REPEATED ITERATION: A WHILE-BASED DYNAMICAL SYSTEM
# ============================================================

@trace
@count_calls
def iterate_system(value, max_iterations=12):
    iteration = 0

    print("\nITERATIVE DYNAMICS")
    print("-" * 40)

    while should_continue(value, iteration):
        previous = value

        if value > 10:
            value = math.sqrt(value)
        elif value > 1:
            value = value / 2
        elif value > 0:
            value = value * 1.5
        else:
            value = abs(value) + 0.1

        # A nonlinear correction.
        if iteration % 2 == 0:
            value = value + math.sin(value)
        else:
            value = value - math.cos(value)

        if not math.isfinite(value):
            print("Numerical instability detected.")
            break
        elif abs(value - previous) < 0.000001:
            print("Approximate convergence detected.")
            break
        else:
            print(
                "Iteration", iteration + 1,
                "| Value:", round(value, 8)
            )

        iteration += 1

        if iteration >= max_iterations:
            print("Maximum iteration limit reached.")
            break

    return value


# ============================================================
# RECURSIVE-STYLE LOGIC WITHOUT RECURSION
# ============================================================

@trace
@count_calls
def symbolic_analysis(history):
    positive = 0
    negative = 0
    zero = 0
    total = 0.0
    index = 0

    while index < len(history):
        step, symbol, value = history[index]

        if value > 0:
            positive += 1
        elif value < 0:
            negative += 1
        else:
            zero += 1

        total += value

        print(
            f"Step {step:02d} | "
            f"Symbol {symbol:>2} | "
            f"Value {value:12.6f}"
        )

        index += 1

    print("\nSTATISTICS")
    print("Positive values:", positive)
    print("Negative values:", negative)
    print("Zero values:", zero)

    if len(history) > 0:
        average = total / len(history)
        print("Average:", round(average, 8))

        if average > 10:
            print("Classification: HIGH MAGNITUDE")
        elif average > 1:
            print("Classification: MODERATE MAGNITUDE")
        else:
            print("Classification: LOW MAGNITUDE")

    return total


# ============================================================
# MAIN PROGRAM
# ============================================================

@trace
def main():
    while True:
        print("\nMENU")
        print("1. Run symbolic sequence")
        print("2. Run iterative system")
        print("3. Show decorator statistics")
        print("4. Exit")

        choice = input("Choose 1-4: ").strip()

        if choice == "1":
            raw = input("Initial number (default 2): ").strip()

            if raw == "":
                initial = 2.0
            else:
                try:
                    initial = float(raw)

                    if not math.isfinite(initial):
                        print("Enter a finite number.")
                        continue

                except ValueError:
                    print("Invalid number.")
                    continue

            history, final_value = run_sequence(initial)
            symbolic_analysis(history)

        elif choice == "2":
            raw = input("Starting value (default 5): ").strip()

            try:
                starting_value = 5.0 if raw == "" else float(raw)

                if not math.isfinite(starting_value):
                    print("Enter a finite number.")
                    continue

                result = iterate_system(starting_value)
                print("Iterative final value:", round(result, 8))

            except ValueError:
                print("Invalid number.")

        elif choice == "3":
            print("\nDECORATOR CALL COUNTS")

            if len(CALL_COUNTS) == 0:
                print("No decorated functions called yet.")
            else:
                for name, count in CALL_COUNTS.items():
                    print(name, ":", count)

        elif choice == "4":
            print("Mathematical machine terminated.")
            break

        else:
            print("Unknown option. Choose 1, 2, 3, or 4.")


if __name__ == "__main__":
    main()


import math
import random
import time
from functools import wraps

# ============================================================
#  THE OBSIDIAN ORRERY
#  A DECORATIVE SYMBOLIC MATHEMATICAL ENGINE
#
#  ] ] @ ? ]! ]$ ]? ![ !@ @@
# ============================================================

SYMBOLS = ["]", "]", "@", "?", "]!", "]$", "]?", "![", "!@", "@@"]

TITLE = "THE OBSIDIAN ORRERY"
VERSION = "2.0 // SYMBOLIC MATHEMATICS"

# Terminal decoration
USE_COLORS = True

COLORS = {
    "reset": "\033[0m",
    "gold": "\033[93m",
    "cyan": "\033[96m",
    "purple": "\033[95m",
    "green": "\033[92m",
    "red": "\033[91m",
    "blue": "\033[94m",
    "white": "\033[97m",
    "dim": "\033[90m",
}


def paint(text, color="white"):
    if not USE_COLORS:
        return str(text)
    return COLORS.get(color, "") + str(text) + COLORS["reset"]


def ornament(char="═", width=68):
    print(paint(char * width, "gold"))


def banner(title):
    ornament("╔")
    print(paint("║ " + title.center(64) + " ║", "cyan"))
    ornament("╚")


def panel(title, value):
    print(paint("  ┌─ " + title + " ─", "purple"))
    print(paint("  │  " + str(value), "white"))
    print(paint("  └" + "─" * 48, "purple"))


def pause():
    time.sleep(0.03)


# ============================================================
# DECORATOR 1: EXECUTION CHRONICLE
# ============================================================

CALLS = {}
TRACE_ENABLED = True


def chronicle(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        name = func.__name__
        CALLS[name] = CALLS.get(name, 0) + 1

        if TRACE_ENABLED:
            print(paint("  ◈ INVOKE :: " + name, "dim"))

        result = func(*args, **kwargs)

        if TRACE_ENABLED:
            print(paint("  ◇ RETURN :: " + name, "dim"))

        return result

    return wrapper


# ============================================================
# DECORATOR 2: MATHEMATICAL VALIDATION
# ============================================================

def validate(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)

        if isinstance(result, (int, float)):
            if not math.isfinite(result):
                raise ArithmeticError("Non-finite result detected.")

        return result

    return wrapper


# ============================================================
# DECORATOR 3: EXECUTION COUNTER
# ============================================================

def counter(func):
    func.total_calls = 0

    @wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.total_calls += 1
        return func(*args, **kwargs)

    wrapper.total_calls = 0
    return wrapper


# ============================================================
# DECORATOR 4: DECORATIVE RESULT DISPLAY
# ============================================================

def illuminated(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        print(paint("  ✧ " + func.__name__ + " → " + str(result), "gold"))
        return result

    return wrapper


# ============================================================
# DECORATOR 5: OPERATION BOUNDARY
# ============================================================

def clamp(low=-1_000_000, high=1_000_000):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            return max(low, min(high, result))

        return wrapper

    return decorator


# ============================================================
# DECORATOR 6: CONDITIONAL DIAGNOSTICS
# ============================================================

def diagnose(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)

        if result == 0:
            print(paint("  [ZERO STATE]", "red"))
        elif abs(result) < 1:
            print(paint("  [MICRO STATE]", "cyan"))
        elif abs(result) > 1000:
            print(paint("  [MACRO STATE]", "purple"))
        else:
            print(paint("  [STABLE STATE]", "green"))

        return result

    return wrapper


# ============================================================
# DECORATOR 7: SYMBOLIC CONTEXT
# ============================================================

def context(label):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            print(paint(f"\n  ⟦ {label.upper()} ⟧", "cyan"))
            return func(*args, **kwargs)

        return wrapper

    return decorator


# ============================================================
# DECORATOR 8: TIMING
# ============================================================

def timed(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start

        print(paint(
            f"  ⏱ {func.__name__}: {elapsed:.6f} seconds",
            "dim"
        ))

        return result

    return wrapper


# ============================================================
# DECORATOR 9: ROUNDING
# ============================================================

def precision(digits=6):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)

            if isinstance(result, float):
                return round(result, digits)

            return result

        return wrapper

    return decorator


# ============================================================
# DECORATOR 10: RETRY A FAILED OPERATION
# ============================================================

def retry(attempts=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0

            while attempt < attempts:
                try:
                    return func(*args, **kwargs)
                except (ValueError, ArithmeticError) as error:
                    attempt += 1
                    print(paint(
                        f"  ! Attempt {attempt}: {error}",
                        "red"
                    ))

            raise ArithmeticError("All attempts failed.")

        return wrapper

    return decorator


# ============================================================
# MATHEMATICAL OPERATION LIBRARY
# ============================================================

@chronicle
@validate
@illuminated
@precision(8)
def addition(a, b):
    return a + b


@chronicle
@validate
@illuminated
@precision(8)
def subtraction(a, b):
    return a - b


@chronicle
@validate
@illuminated
@precision(8)
def multiplication(a, b):
    return a * b


@chronicle
@validate
@illuminated
@precision(8)
def safe_division(a, b):
    if b == 0:
        print(paint("  Division by zero avoided.", "red"))
        return a
    else:
        return a / b


@chronicle
@validate
@illuminated
@precision(8)
def power_operation(a, b):
    if abs(b) > 20:
        b = 20 if b > 0 else -20

    if a == 0 and b < 0:
        return 0

    if a < 0 and not float(b).is_integer():
        return abs(a) ** b

    return a ** b


@chronicle
@validate
@illuminated
@precision(8)
def root_operation(a):
    return math.sqrt(abs(a))


@chronicle
@validate
@illuminated
@precision(8)
def logarithm_operation(a):
    return math.log(abs(a) + 1)


@chronicle
@validate
@illuminated
@precision(8)
def trigonometric_operation(a):
    return math.sin(a) + math.cos(a)


@chronicle
@validate
@illuminated
@precision(8)
def hyperbolic_operation(a):
    return math.tanh(a)


@chronicle
@validate
@illuminated
@precision(8)
def factorial_operation(a):
    n = int(abs(a)) % 13
    return math.factorial(n)


@chronicle
@validate
@illuminated
@precision(8)
def modulo_operation(a, b):
    divisor = abs(int(b))

    if divisor == 0:
        return a
    else:
        return int(a) % divisor


@chronicle
@validate
@illuminated
@precision(8)
def harmonic_operation(a, b):
    if a == 0 or b == 0:
        return 0
    else:
        return 2 * a * b / (a + b) if a + b != 0 else 0


@chronicle
@validate
@illuminated
@precision(8)
def geometric_operation(a, b):
    return math.sqrt(abs(a * b))


# ============================================================
# THE SYMBOL DISPATCHER
# ============================================================

@chronicle
@validate
@clamp()
@diagnose
@context("Symbolic transformation")
def transform(value, symbol, step):

    if symbol == "]":
        if step % 2 == 0:
            result = addition(value, step)
        else:
            result = addition(value, 1)

    elif symbol == "@":
        if step % 3 == 0:
            result = multiplication(value, 2)
        else:
            result = multiplication(value, 1.5)

    elif symbol == "?":
        if value > step:
            result = subtraction(value, step)
        else:
            result = subtraction(step, value)

    elif symbol == "]!":
        result = power_operation(value, 2)

    elif symbol == "]$":
        result = abs(value)

    elif symbol == "]?":
        result = modulo_operation(value, step + 1)

    elif symbol == "![":
        result = root_operation(value)

    elif symbol == "!@":
        result = logarithm_operation(value)

    elif symbol == "@@":
        if step % 2 == 0:
            result = power_operation(value, 2)
        else:
            result = power_operation(value, 3)

    else:
        result = addition(value, 1)

    # Secondary mathematical resonance.
    if step % 4 == 0:
        result = result + math.sin(step)

    elif step % 4 == 1:
        result = result + math.cos(step)

    elif step % 4 == 2:
        result = result + math.tanh(step / 10)

    else:
        result = result + math.log(step + 1)

    return result


# ============================================================
# THE ORRERY: MAIN SEQUENCE
# ============================================================

@chronicle
@timed
@context("The ten gates")
def run_orrery(initial=2.0):

    value = initial
    history = []
    step = 0

    banner(TITLE)
    print(paint("  Sequence: " + " ".join(SYMBOLS), "gold"))
    print(paint("  Initial energy: " + str(value), "green"))
    ornament()

    while step < len(SYMBOLS):

        symbol = SYMBOLS[step]

        print()
        print(paint(
            f"  ✦ GATE {step + 1:02d} / {len(SYMBOLS)}",
            "gold"
        ))

        print(paint("  Symbol: " + symbol, "purple"))
        print(paint("  Incoming: " + str(round(value, 6)), "white"))

        value = transform(value, symbol, step + 1)

        # Nonlinear correction.
        if value > 500:
            print(paint("  [COLLAPSE] Applying square-root damping.", "red"))
            value = math.sqrt(value)

        elif value < -500:
            print(paint("  [INVERSION] Reversing extreme magnitude.", "red"))
            value = -math.sqrt(abs(value))

        elif value > 50:
            print(paint("  [COMPRESSION] Dividing by five.", "purple"))
            value = value / 5

        elif value < 0:
            print(paint("  [INVERSION] Negative state detected.", "cyan"))
            value = abs(value) / 2

        else:
            print(paint("  [RESONANCE] State accepted.", "green"))

        history.append(value)

        panel("CURRENT VALUE", round(value, 8))

        step += 1
        pause()

    ornament()
    print(paint("  THE TEN GATES ARE COMPLETE", "gold"))
    print(paint("  Final value: " + str(round(value, 8)), "cyan"))

    return history, value


# ============================================================
# A SECOND SYSTEM: THE FRACTAL CHAMBER
# ============================================================

@chronicle
@timed
@context("Fractal chamber")
def fractal_chamber(value, iterations=15):

    index = 0
    history = []

    while index < iterations:

        if value < 0:
            value = abs(value)

        if index % 5 == 0:
            value = math.sqrt(value + 1)

        elif index % 5 == 1:
            value = math.sin(value) + 1

        elif index % 5 == 2:
            value = math.cos(value) + 1

        elif index % 5 == 3:
            value = math.log(value + 1)

        else:
            value = (value * value + 1) / (value + 2)

        if not math.isfinite(value):
            print(paint("  Fractal instability!", "red"))
            break

        history.append(value)

        print(
            paint(f"  {index + 1:02d} ▸ ", "purple")
            + paint(f"{value:.8f}", "cyan")
        )

        index += 1

    return history


# ============================================================
# STATISTICAL OBSERVATORY
# ============================================================

@chronicle
@context("Statistical observatory")
def statistics(values):

    if len(values) == 0:
        print(paint("No data available.", "red"))
        return

    total = 0.0
    minimum = values[0]
    maximum = values[0]
    index = 0

    while index < len(values):

        number = values[index]
        total += number

        if number < minimum:
            minimum = number

        if number > maximum:
            maximum = number

        index += 1

    average = total / len(values)

    variance = 0.0
    index = 0

    while index < len(values):
        variance += (values[index] - average) ** 2
        index += 1

    variance /= len(values)

    panel("COUNT", len(values))
    panel("SUM", round(total, 8))
    panel("MEAN", round(average, 8))
    panel("MINIMUM", round(minimum, 8))
    panel("MAXIMUM", round(maximum, 8))
    panel("VARIANCE", round(variance, 8))
    panel("STANDARD DEVIATION", round(math.sqrt(variance), 8))


# ============================================================
# RANDOM ORACLE
# ============================================================

@chronicle
@context("The random oracle")
def oracle():

    value = random.uniform(-10, 10)

    operations = [
        ("SIN", math.sin(value)),
        ("COS", math.cos(value)),
        ("TANH", math.tanh(value)),
        ("SQRT", math.sqrt(abs(value))),
        ("LOG", math.log(abs(value) + 1)),
    ]

    print(paint("  Random seed value: " + str(round(value, 6)), "gold"))

    for name, result in operations:
        print(
            paint("  ◇ " + name.ljust(8), "purple"),
            paint(str(round(result, 8)), "cyan")
        )


# ============================================================
# CALL STATISTICS
# ============================================================

@chronicle
@context("Execution registry")
def show_registry():

    if len(CALLS) == 0:
        print("No recorded operations.")
        return

    for name, count in sorted(CALLS.items()):
        bar = "▰" * min(count, 30)

        print(
            paint("  " + name.ljust(24), "cyan"),
            paint(bar, "gold"),
            count
        )


