"""
============================================================
              THE MATHEMATICAL MULTIVERSE
============================================================

A mathematical laboratory featuring:
    - Multiple implementations of mathematical operations
    - Stacked decorators
    - Execution timing and call counters
    - Logging and verbose mode
    - Cross-checking between algorithms
    - Randomized stress tests
    - Interactive menu

Python standard library only.
Compatible with ordinary Python 3 installations.
"""

import math
import random
import time
from functools import wraps


# ============================================================
# GLOBAL SETTINGS
# ============================================================

VERBOSE = True

IMPLEMENTATIONS = {}
METRICS = {}


# ============================================================
# METRICS
# ============================================================

def metric_for(operation, method):
    key = f"{operation}.{method}"

    if key not in METRICS:
        METRICS[key] = {
            "calls": 0,
            "total_time": 0.0,
            "last_time": 0.0,
            "errors": 0,
        }

    return METRICS[key]


# ============================================================
# DECORATORS
# ============================================================

def logged(func):
    """Print function arguments and results."""

    @wraps(func)
    def wrapper(*args, **kwargs):
        if VERBOSE:
            print(f"  [LOG] Calling {func.__name__}{args}")

        result = func(*args, **kwargs)

        if VERBOSE:
            print(f"  [LOG] Result: {result}")

        return result

    return wrapper


def timed(func):
    """Measure execution time."""

    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()

        try:
            return func(*args, **kwargs)
        finally:
            elapsed = time.perf_counter() - start

            if VERBOSE:
                print(
                    f"  [TIME] {func.__name__}: "
                    f"{elapsed:.8f} seconds"
                )

    return wrapper


def counted(func):
    """Count successful calls and errors."""

    @wraps(func)
    def wrapper(*args, **kwargs):
        operation = getattr(func, "_operation", "unknown")
        method = getattr(func, "_method", func.__name__)
        metrics = metric_for(operation, method)

        metrics["calls"] += 1

        try:
            return func(*args, **kwargs)
        except Exception:
            metrics["errors"] += 1
            raise

    return wrapper


def integer_inputs(func):
    """Require integer arguments, excluding Boolean values."""

    @wraps(func)
    def wrapper(*args, **kwargs):
        values = list(args) + list(kwargs.values())

        for value in values:
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError(
                    "This mathematical operation requires integers."
                )

        return func(*args, **kwargs)

    return wrapper


def announce(func):
    """Announce the mathematical operation."""

    @wraps(func)
    def wrapper(*args, **kwargs):
        if VERBOSE:
            print(f"\n  >>> {func.__name__} begins")

        result = func(*args, **kwargs)

        if VERBOSE:
            print(f"  <<< {func.__name__} finishes")

        return result

    return wrapper


def laboratory(operation, method):
    """
    Register an implementation and apply the decorator stack.
    """

    def decorate(func):
        func._operation = operation
        func._method = method

        wrapped = integer_inputs(func)
        wrapped._operation = operation
        wrapped._method = method

        wrapped = logged(wrapped)
        wrapped._operation = operation
        wrapped._method = method

        wrapped = timed(wrapped)
        wrapped._operation = operation
        wrapped._method = method

        wrapped = counted(wrapped)
        wrapped._operation = operation
        wrapped._method = method

        wrapped = announce(wrapped)
        wrapped._operation = operation
        wrapped._method = method

        IMPLEMENTATIONS.setdefault(operation, {})[method] = wrapped

        return wrapped

    return decorate


# ============================================================
# ADDITION
# ============================================================

@laboratory("add", "built_in")
def add_builtin(a, b):
    return a + b


@laboratory("add", "recursive")
def add_recursive(a, b):
    def calculate(x, y):
        if y == 0:
            return x
        if y > 0:
            return calculate(x + 1, y - 1)
        return calculate(x - 1, y + 1)

    return calculate(a, b)


@laboratory("add", "binary")
def add_binary(a, b):
    """Binary addition using XOR and carry, including negative integers."""

    width = max(a.bit_length(), b.bit_length()) + 2
    mask = (1 << width) - 1
    sign_bit = 1 << (width - 1)

    x = a & mask
    y = b & mask

    while y != 0:
        x, y = (x ^ y) & mask, ((x & y) << 1) & mask

    if x & sign_bit:
        return x - (1 << width)

    return x


# ============================================================
# MULTIPLICATION
# ============================================================

@laboratory("multiply", "built_in")
def multiply_builtin(a, b):
    return a * b


@laboratory("multiply", "repeated_addition")
def multiply_repeated(a, b):
    result = 0
    count = abs(b)

    for _ in range(count):
        result += a

    return -result if b < 0 else result


@laboratory("multiply", "recursive")
def multiply_recursive(a, b):
    def calculate(x, count):
        if count == 0:
            return 0
        return x + calculate(x, count - 1)

    result = calculate(a, abs(b))
    return -result if b < 0 else result


# ============================================================
# EXPONENTIATION
# ============================================================

@laboratory("power", "built_in")
def power_builtin(base, exponent):
    if exponent < 0:
        raise ValueError("Exponent must be non-negative.")
    return base ** exponent


@laboratory("power", "repeated_multiplication")
def power_repeated(base, exponent):
    if exponent < 0:
        raise ValueError("Exponent must be non-negative.")

    result = 1

    for _ in range(exponent):
        result *= base

    return result


@laboratory("power", "recursive")
def power_recursive(base, exponent):
    if exponent < 0:
        raise ValueError("Exponent must be non-negative.")

    def calculate(n):
        if n == 0:
            return 1
        return base * calculate(n - 1)

    return calculate(exponent)


# ============================================================
# FACTORIAL
# ============================================================

@laboratory("factorial", "built_in")
def factorial_builtin(n):
    if n < 0:
        raise ValueError("Factorial is undefined for negative integers.")
    return math.factorial(n)


@laboratory("factorial", "iterative")
def factorial_iterative(n):
    if n < 0:
        raise ValueError("Factorial is undefined for negative integers.")

    result = 1

    for number in range(2, n + 1):
        result *= number

    return result


@laboratory("factorial", "recursive")
def factorial_recursive(n):
    if n < 0:
        raise ValueError("Factorial is undefined for negative integers.")

    def calculate(number):
        if number <= 1:
            return 1
        return number * calculate(number - 1)

    return calculate(n)


# ============================================================
# GREATEST COMMON DIVISOR
# ============================================================

@laboratory("gcd", "euclidean")
def gcd_euclidean(a, b):
    return math.gcd(a, b)


@laboratory("gcd", "subtraction")
def gcd_subtraction(a, b):
    a = abs(a)
    b = abs(b)

    if a == 0:
        return b
    if b == 0:
        return a

    while a != b:
        if a > b:
            a -= b
        else:
            b -= a

    return a


# ============================================================
# TRIANGULAR NUMBERS
# ============================================================

@laboratory("triangular", "formula")
def triangular_formula(n):
    if n < 0:
        raise ValueError("n must be non-negative.")
    return n * (n + 1) // 2


@laboratory("triangular", "iterative")
def triangular_iterative(n):
    if n < 0:
        raise ValueError("n must be non-negative.")

    total = 0

    for number in range(1, n + 1):
        total += number

    return total


@laboratory("triangular", "recursive")
def triangular_recursive(n):
    if n < 0:
        raise ValueError("n must be non-negative.")

    def calculate(number):
        if number == 0:
            return 0
        return number + calculate(number - 1)

    return calculate(n)


# ============================================================
# CROSS-CHECKING
# ============================================================

def cross_check(operation, *args):
    print("\n" + "=" * 60)
    print(f"CROSS-CHECK: {operation.upper()} {args}")
    print("=" * 60)

    methods = IMPLEMENTATIONS[operation]
    results = {}
    previous_verbose = VERBOSE

    try:
        # Suppress decorator output while comparing algorithms.
        set_verbose(False)

        for name, function in methods.items():
            try:
                results[name] = function(*args)
            except (ValueError, TypeError, ArithmeticError,
                    RecursionError) as error:
                results[name] = f"ERROR: {error}"

    finally:
        set_verbose(previous_verbose)

    successful = [
        (name, result)
        for name, result in results.items()
        if not isinstance(result, str)
        or not result.startswith("ERROR:")
    ]

    for name, result in results.items():
        print(f"{name:25} -> {result}")

    if not successful:
        print("\nNo implementation produced a result.")
        return False

    values = [result for _, result in successful]
    consistent = all(value == values[0] for value in values)

    print("-" * 60)

    if consistent and len(successful) == len(results):
        print("RESULT: ALL IMPLEMENTATIONS AGREE")
    elif consistent:
        print("RESULT: SUCCESSFUL IMPLEMENTATIONS AGREE")
        print("Some implementations could not handle this input.")
    else:
        print("RESULT: DISAGREEMENT DETECTED!")

    return consistent and len(successful) == len(results)


# ============================================================
# VERBOSE MODE
# ============================================================

def set_verbose(enabled):
    global VERBOSE
    VERBOSE = enabled


# ============================================================
# RANDOMIZED STRESS TESTING
# ============================================================

def random_arguments(operation):
    if operation == "add":
        return (
            random.randint(-100, 100),
            random.randint(-100, 100),
        )

    if operation == "multiply":
        return (
            random.randint(-30, 30),
            random.randint(-30, 30),
        )

    if operation == "power":
        return (
            random.randint(-5, 5),
            random.randint(0, 10),
        )

    if operation == "factorial":
        return (random.randint(0, 12),)

    if operation == "gcd":
        return (
            random.randint(-500, 500),
            random.randint(-500, 500),
        )

    if operation == "triangular":
        return (random.randint(0, 300),)

    raise ValueError("Unknown operation.")


def stress_test(operation, tests=100):
    print("\n" + "=" * 60)
    print(f"RANDOMIZED STRESS TEST: {operation.upper()}")
    print(f"Number of test cases: {tests}")
    print("=" * 60)

    methods = IMPLEMENTATIONS[operation]
    previous_verbose = VERBOSE
    passed = 0
    failures = []

    try:
        set_verbose(False)

        for case_number in range(1, tests + 1):
            args = random_arguments(operation)
            results = {}

            for name, function in methods.items():
                try:
                    results[name] = function(*args)
                except (ValueError, TypeError, ArithmeticError,
                        RecursionError) as error:
                    results[name] = f"ERROR: {error}"

            valid_results = [
                value for value in results.values()
                if not isinstance(value, str)
                or not value.startswith("ERROR:")
            ]

            all_succeeded = len(valid_results) == len(methods)
            all_agree = (
                bool(valid_results)
                and all(value == valid_results[0]
                        for value in valid_results)
            )

            if all_succeeded and all_agree:
                passed += 1
            else:
                failures.append((case_number, args, results))

    finally:
        set_verbose(previous_verbose)

    print(f"\nPassed: {passed}/{tests}")
    print(f"Failed: {tests - passed}/{tests}")

    if failures:
        print("\nFirst five disagreements or errors:")

        for case_number, args, results in failures[:5]:
            print(f"\nCase {case_number}, arguments={args}")

            for name, result in results.items():
                print(f"  {name}: {result}")

    if passed == tests:
        print("\nALL TESTS PASSED!")

    return passed == tests


# ============================================================
# PERFORMANCE REPORT
# ============================================================

def show_metrics():
    print("\n" + "=" * 78)
    print("MATHEMATICAL MULTIVERSE — PERFORMANCE REPORT")
    print("=" * 78)

    print(
        f"{'OPERATION.METHOD':35}"
        f"{'CALLS':>10}"
        f"{'ERRORS':>10}"
        f"{'TOTAL (s)':>13}"
        f"{'AVERAGE (s)':>13}"
    )

    print("-" * 78)

    for key in sorted(METRICS):
        data = METRICS[key]
        calls = data["calls"]
        average = data["total_time"] / calls if calls else 0.0

        print(
            f"{key:35}"
            f"{calls:>10}"
            f"{data['errors']:>10}"
            f"{data['total_time']:>13.8f}"
            f"{average:>13.8f}"
        )

    if not METRICS:
        print("No measurements recorded yet.")

    print("=" * 78)


# ============================================================
# SAFE INTERACTIVE INPUT
# ============================================================

def read_integer(prompt):
    while True:
        value = input(prompt).strip()

        try:
            return int(value)
        except ValueError:
            print("Please enter a valid integer.")


def choose_operation():
    operations = list(IMPLEMENTATIONS.keys())

    print("\nAvailable mathematical operations:")

    for index, operation in enumerate(operations, start=1):
        print(f"  {index}. {operation}")

    while True:
        choice = read_integer("Choose an operation: ")

        if 1 <= choice <= len(operations):
            return operations[choice - 1]

        print("Invalid choice.")


def perform_operation():
    operation = choose_operation()

    if operation in ("factorial", "triangular"):
        n = read_integer("Enter n: ")

        if operation == "factorial" and not 0 <= n <= 500:
            print("For this laboratory, factorial input must be 0–500.")
            return

        if operation == "triangular" and not 0 <= n <= 500:
            print("For this laboratory, triangular input must be 0–500.")
            return

        args = (n,)

    elif operation == "power":
        base = read_integer("Enter the base: ")
        exponent = read_integer("Enter the exponent (0–100): ")

        if not 0 <= exponent <= 100:
            print("Exponent must be between 0 and 100.")
            return

        args = (base, exponent)

    else:
        a = read_integer("Enter the first integer: ")
        b = read_integer("Enter the second integer: ")
        args = (a, b)

    cross_check(operation, *args)


# ============================================================
# MAIN MENU
# ============================================================

def main():
    global VERBOSE

    while True:
        print("\n")
        print("*" * 60)
        print("       THE MATHEMATICAL MULTIVERSE")
        print("*" * 60)
        print("  1. Calculate and cross-check")
        print("  2. Run a randomized stress test")
        print("  3. Show performance metrics")
        print("  4. Toggle verbose decorator output")
        print("  5. Show available algorithms")
        print("  0. Exit")
        print("*" * 60)
        print(f"  Verbose mode: {'ON' if VERBOSE else 'OFF'}")

        choice = input("\nYour choice: ").strip()

        if choice == "1":
            perform_operation()

        elif choice == "2":
            operation = choose_operation()
            tests = read_integer("Number of test cases (1–1000): ")

            if not 1 <= tests <= 1000:
                print("Choose between 1 and 1000 test cases.")
                continue

            stress_test(operation, tests)

        elif choice == "3":
            show_metrics()

        elif choice == "4":
            VERBOSE = not VERBOSE
            print(f"Verbose mode is now {'ON' if VERBOSE else 'OFF'}.")

        elif choice == "5":
            print("\nREGISTERED ALGORITHMS")

            for operation, methods in IMPLEMENTATIONS.items():
                print(f"\n{operation.upper()}")

                for method in methods:
                    print(f"  - {method}")

        elif choice == "0":
            print("\nClosing the Mathematical Multiverse. Goodbye!")
            break

        else:
            print("Invalid choice. Try again.")


# ============================================================
# ENTRY POINT
# ============================================================

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""THE MATHEMATICAL MULTIVERSE — decorators and operations edition.

A single-file Python laboratory featuring decorators, arithmetic, number
theory, sequences, geometry, cross-checking, randomized tests, and metrics.
Uses only the Python standard library.
"""

import functools
import math
import random
import time
from collections import Counter

VERBOSE = False
CALLS = Counter()
ERRORS = Counter()
SECONDS = Counter()
REGISTRY = {}


def counted(func):
    """Count successful calls and errors."""
    name = func.__name__

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        CALLS[name] += 1
        try:
            return func(*args, **kwargs)
        except Exception:
            ERRORS[name] += 1
            raise
    return wrapper


def timed(func):
    """Accumulate elapsed time."""
    name = func.__name__

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return func(*args, **kwargs)
        finally:
            SECONDS[name] += time.perf_counter() - start
    return wrapper


def logged(func):
    """Log inputs and outputs when verbose mode is enabled."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if VERBOSE:
            print("[CALL]", func.__name__, args, kwargs)
        result = func(*args, **kwargs)
        if VERBOSE:
            print("[RETURN]", func.__name__, "=", result)
        return result
    return wrapper


def integer_arguments(func):
    """Validate that all supplied arguments are integers, not booleans."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        for value in list(args) + list(kwargs.values()):
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError("This operation expects integer arguments.")
        return func(*args, **kwargs)
    return wrapper


def registered(func):
    """Add a function to the interactive operation registry."""
    REGISTRY[func.__name__] = func
    return func


def mathematical_operation(func):
    """The standard decorator stack used by the core operations."""
    func = integer_arguments(func)
    func = logged(func)
    func = timed(func)
    func = counted(func)
    func = registered(func)
    return func


@mathematical_operation
def add(a, b):
    return a + b


@mathematical_operation
def subtract(a, b):
    return a - b


@mathematical_operation
def multiply(a, b):
    return a * b


@mathematical_operation
def divide(a, b):
    if b == 0:
        raise ZeroDivisionError("Cannot divide by zero.")
    return a / b


@mathematical_operation
def integer_divide(a, b):
    if b == 0:
        raise ZeroDivisionError("Cannot divide by zero.")
    return a // b


@mathematical_operation
def modulo(a, b):
    if b == 0:
        raise ZeroDivisionError("Cannot calculate modulo zero.")
    return a % b


@mathematical_operation
def power(a, b):
    if b < 0:
        raise ValueError("This integer power operation needs b >= 0.")
    return pow(a, b)


@mathematical_operation
def gcd(a, b):
    return math.gcd(a, b)


@mathematical_operation
def lcm(a, b):
    return math.lcm(a, b)


@mathematical_operation
def factorial(n):
    if n < 0:
        raise ValueError("n must be non-negative.")
    return math.factorial(n)


@mathematical_operation
def fibonacci(n):
    if n < 0:
        raise ValueError("n must be non-negative.")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


@mathematical_operation
def triangular(n):
    if n < 0:
        raise ValueError("n must be non-negative.")
    return n * (n + 1) // 2


@mathematical_operation
def is_prime(n):
    if n < 2:
        return 0
    if n == 2:
        return 1
    if n % 2 == 0:
        return 0
    for divisor in range(3, math.isqrt(n) + 1, 2):
        if n % divisor == 0:
            return 0
    return 1


@mathematical_operation
def digit_sum(n):
    return sum(int(character) for character in str(abs(n)))


@mathematical_operation
def reverse_integer(n):
    sign = -1 if n < 0 else 1
    return sign * int(str(abs(n))[::-1])


@mathematical_operation
def binomial(n, k):
    if n < 0 or k < 0 or k > n:
        raise ValueError("Require n >= k >= 0.")
    return math.comb(n, k)


@mathematical_operation
def bitwise_and(a, b):
    return a & b


@mathematical_operation
def bitwise_or(a, b):
    return a | b


@mathematical_operation
def bitwise_xor(a, b):
    return a ^ b


@mathematical_operation
def absolute_difference(a, b):
    return abs(a - b)


@mathematical_operation
def maximum(a, b):
    return max(a, b)


@mathematical_operation
def minimum(a, b):
    return min(a, b)


def memoized(func):
    """Memoize results for hashable arguments."""
    cache = {}

    @functools.wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]

    wrapper.cache = cache
    return wrapper


@memoized
def cached_fibonacci(n):
    if n < 0:
        raise ValueError("n must be non-negative.")
    if n < 2:
        return n
    return cached_fibonacci(n - 1) + cached_fibonacci(n - 2)


def circle_area(radius):
    if radius < 0:
        raise ValueError("Radius must be non-negative.")
    return math.pi * radius * radius


def circle_circumference(radius):
    if radius < 0:
        raise ValueError("Radius must be non-negative.")
    return 2 * math.pi * radius


def rectangle_area(width, height):
    if width < 0 or height < 0:
        raise ValueError("Dimensions must be non-negative.")
    return width * height


def distance_2d(x1, y1, x2, y2):
    return math.hypot(x2 - x1, y2 - y1)


def moving_average(values, window):
    values = list(values)
    if window < 1 or window > len(values):
        raise ValueError("Invalid window size.")
    return [
        sum(values[index:index + window]) / window
        for index in range(len(values) - window + 1)
    ]


def show_operations():
    print("\nAVAILABLE DECORATED OPERATIONS")
    for name in sorted(REGISTRY):
        print(" ", name)


def show_metrics():
    print("\nOPERATION METRICS")
    print(f"{'NAME':24} {'CALLS':>10} {'ERRORS':>10} {'SECONDS':>14}")
    print("-" * 62)
    for name in sorted(set(CALLS) | set(ERRORS) | set(SECONDS)):
        print(
            f"{name:24} {CALLS[name]:>10} {ERRORS[name]:>10} "
            f"{SECONDS[name]:>14.8f}"
        )


def self_test():
    cases = [
        ("add", (2, 3), 5),
        ("subtract", (9, 4), 5),
        ("multiply", (7, 8), 56),
        ("divide", (9, 3), 3.0),
        ("integer_divide", (10, 3), 3),
        ("modulo", (10, 3), 1),
        ("power", (2, 10), 1024),
        ("gcd", (48, 18), 6),
        ("lcm", (12, 18), 36),
        ("factorial", (5,), 120),
        ("fibonacci", (10,), 55),
        ("triangular", (10,), 55),
        ("is_prime", (29,), 1),
        ("digit_sum", (12345,), 15),
        ("binomial", (6, 2), 15),
    ]
    failed = []
    for name, args, expected in cases:
        actual = REGISTRY[name](*args)
        if actual != expected:
            failed.append((name, args, expected, actual))
    print(f"SELF-TEST: {len(cases) - len(failed)}/{len(cases)} passed")
    for failure in failed:
        print("FAILED:", failure)
    return not failed


def random_test(rounds=100):
    """Compare selected operations with Python's built-in arithmetic."""
    passed = 0
    for _ in range(rounds):
        a = random.randint(-1000, 1000)
        b = random.randint(-1000, 1000)
        checks = [
            (REGISTRY["add"](a, b), a + b),
            (REGISTRY["subtract"](a, b), a - b),
            (REGISTRY["multiply"](a, b), a * b),
            (REGISTRY["gcd"](a, b), math.gcd(a, b)),
        ]
        if all(actual == expected for actual, expected in checks):
            passed += 1
    print(f"RANDOM TEST: {passed}/{rounds} cases passed")
    return passed == rounds


def read_integer(prompt):
    while True:
        try:
            return int(input(prompt).strip())
        except ValueError:
            print("Please enter an integer.")


def run_operation():
    show_operations()
    name = input("\nOperation name: ").strip()
    if name not in REGISTRY:
        print("Unknown operation.")
        return
    raw = input("Integer arguments separated by spaces: ").strip()
    try:
        args = tuple(int(part) for part in raw.split())
        print("RESULT:", REGISTRY[name](*args))
    except Exception as error:
        print(type(error).__name__ + ":", error)


def main():
    global VERBOSE
    while True:
        print("\n" + "=" * 58)
        print("          THE MATHEMATICAL MULTIVERSE")
        print("=" * 58)
        print("1. Run an operation")
        print("2. List operations")
        print("3. Show decorator metrics")
        print("4. Run self-test")
        print("5. Run randomized tests")
        print("6. Toggle verbose logging")
        print("0. Exit")
        choice = input("Choice: ").strip()

        if choice == "1":
            run_operation()
        elif choice == "2":
            show_operations()
        elif choice == "3":
            show_metrics()
        elif choice == "4":
            self_test()
        elif choice == "5":
            rounds = read_integer("Number of test rounds (1-10000): ")
            if 1 <= rounds <= 10000:
                random_test(rounds)
            else:
                print("Choose a value from 1 to 10000.")
        elif choice == "6":
            VERBOSE = not VERBOSE
            print("Verbose logging:", "ON" if VERBOSE else "OFF")
        elif choice == "0":
            print("The Multiverse is closing. Goodbye!")
            break
        else:
            print("Invalid choice.")


if __name__ == "__main__":
    print("Loaded", len(REGISTRY), "decorated operations.")
    self_test()
    main()

